FUNCTION_BLOCK FB
VAR_INPUT
    demand: INT;
    runHours: ARRAY[1..5] OF LINT;
    rotated: BOOL;
END_VAR
VAR_OUTPUT
    leadPump: INT;
    lagPump: INT;
    runningCount: INT;
END_VAR
VAR
    prevLeadPump: INT := 0;
    prevLagPump: INT := 0;
    prevRunningCount: INT := 0;
    clippedDemand: INT;
    minHours: LINT;
    bestPump: INT;
    i: INT;
END_VAR

// Implementation

// Clip demand to 0..5
IF demand < 0 THEN
    clippedDemand := 0;
ELSIF demand > 5 THEN
    clippedDemand := 5;
ELSE
    clippedDemand := demand;
END_IF

runningCount := clippedDemand;

// Compute global minimum run hours and corresponding pump (tie-break smallest index)
minHours := runHours[1];
bestPump := 1;
FOR i := 2 TO 5 DO
    IF runHours[i] < minHours THEN
        minHours := runHours[i];
        bestPump := i;
    END_IF
END_FOR

IF clippedDemand = 0 THEN
    leadPump := 0;
    lagPump := 0;
ELSE
    // Positive demand: determine lead pump
    IF prevLeadPump = 0 THEN
        // Initial selection: pump with smallest run hours
        leadPump := bestPump;
    ELSE
        // Already have a lead pump: consider rotation request
        IF rotated AND (runHours[prevLeadPump] - minHours > LINT#50) THEN
            leadPump := bestPump;
        ELSE
            leadPump := prevLeadPump;
        END_IF
    END_IF

    // Determine lag pump
    IF clippedDemand < 2 THEN
        lagPump := 0;
    ELSE
        // Need a lag pump; recompute only on initial selection, lead change, or running count increase
        IF (prevLeadPump = 0) OR (leadPump <> prevLeadPump) OR (clippedDemand > prevRunningCount) THEN
            // Select the pump with smallest run hours excluding the current lead pump
            lagPump := 0;
            minHours := LINT#16#7FFFFFFFFFFFFFFF;
            FOR i := 1 TO 5 DO
                IF i = leadPump THEN
                    // skip lead pump
                ELSE
                    IF runHours[i] < minHours THEN
                        minHours := runHours[i];
                        lagPump := i;
                    END_IF
                END_IF
            END_FOR
        ELSE
            // Keep previous lag pump
            lagPump := prevLagPump;
        END_IF
    END_IF
END_IF

// Update previous state for next scan
prevLeadPump := leadPump;
prevLagPump := lagPump;
prevRunningCount := runningCount;

END_FUNCTION_BLOCK

